<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Shop administration | XenoPixels</title><link rel="stylesheet" href="/assets/shop.css?v=2"><link rel="stylesheet" href="/assets/interactions.css"></head>
<body><?php require __DIR__ . '/topnav.php'; ?><main><section class="hero"><p class="eyebrow">ADMINISTRATION</p><h1>Products & rewards</h1><p>Rewards accept item and allow-listed kit entries only. Never enter console commands.</p></section>
<section class="admin-layout"><form id="product-form" class="card card-body" action="/admin" method="post" data-csrf="<?= htmlspecialchars($csrfToken, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') ?>"><h2>Add product</h2><input type="hidden" name="csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') ?>"><input type="hidden" name="id" value=""><label>Product slug<input name="slug" required maxlength="80" pattern="[a-z0-9_-]+"></label><label>Title<input name="title" required maxlength="120"></label><label>Description<textarea name="description" maxlength="8000"></textarea></label><label>Image URL (HTTPS)<input name="image_url" type="url" maxlength="500"></label><div class="form-row"><label>Web price, minor units<input name="web_price_minor" type="number" min="1"></label><label>Web currency<input name="web_currency" maxlength="3" placeholder="USD"></label></div><div class="form-row"><label>MMO Econ price<input name="mmoecon_price" type="number" min="1"></label><label>Zeni cash price<input name="zeni_cash_price" type="number" min="1"></label></div><label>Reward JSON<textarea name="reward_json" required rows="5">[{"type":"item","item":"minecraft:diamond","count":1}]</textarea></label><label class="check"><input name="enabled" type="checkbox" value="1"> Enable product</label><button class="button" type="submit">Save product</button><output id="admin-result" aria-live="polite"><?php if (!empty($savedProductId)): ?>Saved product #<?= (int)$savedProductId ?>.<?php endif; ?></output></form>
<section><h2>Current catalog</h2><div class="grid"><?php foreach ($products as $product): ?><article class="card card-body"><p class="eyebrow">#<?= (int)$product['id'] ?> · <?= $product['enabled'] ? 'ENABLED' : 'DISABLED' ?></p><h3><?= htmlspecialchars($product['title'], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') ?></h3><p><?= htmlspecialchars($product['slug'], ENT_QUOTES, 'UTF-8') ?></p><details><summary>Reward definition</summary><pre><?= htmlspecialchars($product['reward_json'], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') ?></pre></details><button class="button edit-product" type="button" data-product="<?= htmlspecialchars(json_encode($product, JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT), ENT_QUOTES, 'UTF-8') ?>">Edit</button></article><?php endforeach; ?></div></section></section></main><script src="/assets/shop.js?v=0.1.1" defer></script></body></html>
